const fs = require('fs');
const path = require('path');

// Extract or load LTC logo base64
let LTC_BASE64 = "data:image/png;base64,";
if (!LTC_BASE64) {
  try {
    const tplPath = path.join(__dirname, '..', '..', 'LTC 5-Day Residential Program Report Template (1).html');
    if (fs.existsSync(tplPath)) {
      const tplHtml = fs.readFileSync(tplPath, 'utf8');
      const m = tplHtml.match(/var\s+LTC\s*=\s*["']([^"']+)["']/);
      if (m && m[1]) LTC_BASE64 = m[1];
    }
  } catch (_) {}
}

// Load WPU logo base64
let WPU_DATA_URI = '';
try {
  const wpuLogoPath = path.join(__dirname, '..', 'assets', 'mit_wpu_logo.png');
  if (fs.existsSync(wpuLogoPath)) {
    const wpuBase64 = fs.readFileSync(wpuLogoPath).toString('base64');
    WPU_DATA_URI = `data:image/png;base64,${wpuBase64}`;
  }
} catch (_) {}

const esc = (str) => {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

const formatBatchDates = (startStr, endStr) => {
  try {
    if (!startStr || !endStr) return "19th to 23rd April 2026.";
    const dStart = new Date(startStr);
    const dEnd = new Date(endStr);
    if (isNaN(dStart.getTime()) || isNaN(dEnd.getTime())) return "19th to 23rd April 2026.";
    const getOrdinal = (d) => {
      if (d > 3 && d < 21) return 'th';
      switch (d % 10) {
        case 1:  return "st";
        case 2:  return "nd";
        case 3:  return "rd";
        default: return "th";
      }
    };

    const startDay = dStart.getDate();
    const startOrd = getOrdinal(startDay);
    const endDay = dEnd.getDate();
    const endOrd = getOrdinal(endDay);
    const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
    const startMonth = months[dStart.getMonth()];
    const endMonth = months[dEnd.getMonth()];
    const year = dEnd.getFullYear();

    if (startMonth === endMonth) {
      return `${startDay}${startOrd} to ${endDay}${endOrd} ${endMonth} ${year}`;
    } else {
      return `${startDay}${startOrd} ${startMonth} to ${endDay}${endOrd} ${endMonth} ${year}`;
    }
  } catch (_) {
    return "19th to 23rd April 2026.";
  }
};

const formatDate = (d) => {
  if (!d) return '';
  try {
    const dt = new Date(d);
    if (isNaN(dt.getTime())) return String(d);
    const day = String(dt.getDate()).padStart(2, '0');
    const month = String(dt.getMonth() + 1).padStart(2, '0');
    const year = dt.getFullYear();
    return `${day}/${month}/${year}`;
  } catch (_) {
    return String(d);
  }
};

